/// <summary>
///  designed from AVA
/// </summary>
/// <param name="sender">sender</param>
/// <param name="e">e</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    DataEventHandler(tableStr(SalesTable), DataEventType::Inserted)]
public static void SalesTable_onInserted(Common sender, DataEventArgs e)
{
    SalesTable          salesTable = sender;
    AVASpecialDiscSalesOrder::createFromSalesTable(salesTable);    
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name="sender">sender</param>
/// <param name="e">e</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    DataEventHandler(tableStr(SalesTable), DataEventType::Deleted)]
public static void SalesTable_onDeleted(Common sender, DataEventArgs e)
{
    SalesTable                      salesTable = sender;

    AVASpecialDiscSalesOrder        specialDiscSalesOrder;

    delete_from specialDiscSalesOrder
        where specialDiscSalesOrder.SalesId == salesTable.SalesId;
}
